3.2 Parttern 2. Use DuckDB as a dplyr backend (no SQL required)

If you prefer dplyr verbs over SQL, you can register the Parquet file as a virtual table and query it lazily.
dbplyr translates dplyr verbs into DuckDB SQL automatically:


3.2.1 Simple:


Code
```{r}
#| eval: false
library(duckdb)
library(dplyr)
library(dbplyr)
library(DBI)

con &lt;- dbConnect(duckdb())

duckdb_register(con, "sales", read_parquet("data/sales.parquet"))

tbl(con, "sales") |&gt;
  filter(year &gt;= 2022) |&gt;
  group_by(region) |&gt;
  summarise(total = sum(sales)) |&gt;
  arrange(desc(total)) |&gt;
  collect()   # only now does data enter R
```




3.2.2 Advanced:


Code
```{r}
#| eval: false
library(duckdb)
library(dplyr)
library(dbplyr)
library(DBI)

con &lt;- dbConnect(duckdb())

# ── Register Parquet file as a virtual table ───────────────────────────────────
# This creates a view — no data is copied or loaded
duckdb_read_csv   # (there is also this for CSV)

dbExecute(con, "
  CREATE VIEW ga4_events AS
  SELECT * FROM read_parquet('data/ga4_flat.parquet')
")

dbExecute(con, "
  CREATE VIEW ga4_sessions AS
  SELECT * FROM read_parquet('data/ga4_sessions.parquet')
")

# ── Now use dplyr as if it were a regular data frame ──────────────────────────
events   &lt;- tbl(con, "ga4_events")
sessions &lt;- tbl(con, "ga4_sessions")

# dplyr query — translated to DuckDB SQL by dbplyr
top_events &lt;- events |&gt;
  count(event_name, sort = TRUE) |&gt;
  head(10) |&gt;
  collect()    # collect() executes the query and returns a tibble

print(top_events)

# Join two Parquet files using dplyr — no SQL written
device_conversions &lt;- sessions |&gt;
  select(user_pseudo_id, device_category, traffic_source_medium) |&gt;
  left_join(
    events |&gt;
      filter(event_name == "purchase") |&gt;
      distinct(user_pseudo_id) |&gt;
      mutate(purchased = TRUE),
    by = "user_pseudo_id"
  ) |&gt;
  mutate(purchased = coalesce(purchased, FALSE)) |&gt;
  group_by(device_category, traffic_source_medium) |&gt;
  summarise(
    users      = n_distinct(user_pseudo_id),
    purchasers = sum(as.integer(purchased), na.rm = TRUE),
    cvr        = purchasers / users,
    .groups    = "drop"
  ) |&gt;
  arrange(desc(cvr)) |&gt;
  collect()  # only now does data enter R

print(device_conversions)

dbDisconnect(con, shutdown = TRUE)
```

4.2 When to use which

Use collect() when you’re done querying and need the data in R for plotting, modeling, or export.
Use compute() when your query is complex/expensive and you want to cache an intermediate result in the database to build further queries on top of it — avoiding recomputation.


4.2.1 Use Case
A common pattern is to use compute() for heavy intermediate transformations, then collect() at the very end:
```{r}
filtered &lt;- tbl(con, "big_table") |&gt;
  filter(status == "active") |&gt;
  group_by(region) |&gt;
  summarise(n = n()) |&gt;
  compute() # Cache this aggregation in the DB

final &lt;- filtered |&gt;
  filter(n &gt; 100) |&gt;
  collect() # Now bring into R
```

