8.4.3 Performance Attribution






ImportantAttribution




Partitioning improves performance because this query uses CheckoutYear == 2021 to filter the data, and arrow is smart enough to recognize that it only needs to read 1 of the 18 parquet files.
Storing data in binary format can be read more directly into memory
The column-wise format and rich metadata means only four columns are needed: CheckoutYear, MaterialType, CheckoutMonth, and Checkouts

5.2 Analysis 1: Event Volume Overview


Code
```{r}
#| eval: false

# ── Identical to dplyr — but DuckDB executes it ───────────────────────────────
event_summary &lt;- ga4_events |&gt;
  group_by(event_name) |&gt;
  summarise(
    total_events = n(),
    unique_users = n_distinct(user_pseudo_id),
    unique_days = n_distinct(event_date),
    events_per_day = round(total_events / unique_days, 1),
    .groups = "drop"
  ) |&gt;
  arrange(desc(total_events))

# Result is already a tibble — no collect() needed
event_summary |&gt;
  gt() |&gt;
  tab_header(
    title = "GA4 Event Summary",
    subtitle = "Computed by DuckDB via duckplyr"
  ) |&gt;
  fmt_number(columns = c(total_events, unique_users), decimals = 0) |&gt;
  fmt_number(columns = events_per_day, decimals = 1) |&gt;
  cols_label(
    event_name = "Event",
    total_events = "Total Events",
    unique_users = "Unique Users",
    unique_days = "Days",
    events_per_day = "Events/Day"
  ) |&gt;
  opt_stylize(style = 1)
```

5.3 Analysis 2: Traffic Source Performance


Code
```{r}
#| eval: false

# ── Join sessions with purchase events ────────────────────────────────────────
# duckplyr handles joins the same as dplyr
purchasers &lt;- ga4_events |&gt;
  filter(event_name == "purchase") |&gt;
  distinct(user_pseudo_id) |&gt;
  mutate(purchased = TRUE)

traffic_performance &lt;- ga4_sessions |&gt;
  mutate(
    channel = case_when(
      is.na(traffic_source_medium) |
        traffic_source_medium == "(none)" ~ "Direct",
      traffic_source_medium == "organic" ~ "Organic Search",
      traffic_source_medium %in% c("cpc", "ppc") ~ "Paid Search",
      str_detect(traffic_source_medium, "email") ~ "Email",
      str_detect(traffic_source_medium, "social") ~ "Social",
      TRUE ~ str_to_title(traffic_source_medium)
    )
  ) |&gt;
  group_by(channel) |&gt;
  summarise(
    sessions = n(),
    unique_users = n_distinct(user_pseudo_id),
    .groups = "drop"
  ) |&gt;
  left_join(
    ga4_sessions |&gt;
      mutate(
        channel = case_when(
          is.na(traffic_source_medium) |
            traffic_source_medium == "(none)" ~ "Direct",
          traffic_source_medium == "organic" ~ "Organic Search",
          traffic_source_medium %in% c("cpc", "ppc") ~ "Paid Search",
          str_detect(traffic_source_medium, "email") ~ "Email",
          str_detect(traffic_source_medium, "social") ~ "Social",
          TRUE ~ str_to_title(traffic_source_medium)
        )
      ) |&gt;
      select(user_pseudo_id, channel) |&gt;
      left_join(purchasers, by = "user_pseudo_id") |&gt;
      group_by(channel) |&gt;
      summarise(
        converters = sum(as.integer(!is.na(purchased)), na.rm = TRUE),
        .groups = "drop"
      ),
    by = "channel"
  ) |&gt;
  mutate(
    cvr = converters / unique_users,
    sessions_pct = sessions / sum(sessions)
  ) |&gt;
  arrange(desc(sessions))

traffic_performance |&gt;
  gt() |&gt;
  tab_header(title = "Traffic Channel Performance") |&gt;
  fmt_number(columns = c(sessions, unique_users, converters), decimals = 0) |&gt;
  fmt_percent(columns = c(cvr, sessions_pct), decimals = 1) |&gt;
  cols_label(
    channel = "Channel",
    sessions = "Sessions",
    unique_users = "Users",
    converters = "Buyers",
    cvr = "CVR",
    sessions_pct = "% of Sessions"
  ) |&gt;
  data_color(
    columns = cvr,
    method = "numeric",
    palette = c("#ffffff", "#43a04740")
  ) |&gt;
  opt_stylize(style = 1)
```

5.7 Analysis 6: Product Performance (from ga4_items)


Code
```{r}
#| eval: false

# ── Top products and categories ────────────────────────────────────────────────
product_performance &lt;- ga4_items |&gt;
  filter(!is.na(item_name)) |&gt;
  group_by(item_category, item_name) |&gt;
  summarise(
    units_sold = sum(quantity, na.rm = TRUE),
    revenue = sum(item_revenue_in_usd, na.rm = TRUE),
    transactions = n_distinct(event_timestamp),
    avg_price = mean(price_in_usd, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  arrange(desc(revenue))

# Category rollup
category_summary &lt;- product_performance |&gt;
  group_by(item_category) |&gt;
  summarise(
    products = n_distinct(item_name),
    revenue = sum(revenue),
    units = sum(units_sold),
    .groups = "drop"
  ) |&gt;
  mutate(
    revenue_pct = revenue / sum(revenue),
    item_category = fct_reorder(item_category, revenue)
  ) |&gt;
  arrange(desc(revenue))

category_summary |&gt;
  gt() |&gt;
  tab_header(title = "Revenue by Product Category") |&gt;
  fmt_number(columns = c(products, units), decimals = 0) |&gt;
  fmt_currency(columns = revenue, currency = "USD") |&gt;
  fmt_percent(columns = revenue_pct, decimals = 1) |&gt;
  cols_label(
    item_category = "Category",
    products = "Products",
    revenue = "Revenue",
    units = "Units Sold",
    revenue_pct = "Revenue Share"
  ) |&gt;
  data_color(
    columns = revenue,
    method = "numeric",
    palette = c("#e3f2fd", "#1565c0")
  ) |&gt;
  opt_stylize(style = 1)
```

5.8 Analysis 7: User Segmentation


Code
```{r}
#| eval: false

# ── New vs returning user behaviour ───────────────────────────────────────────
user_segments &lt;- ga4_params |&gt;
  filter(key == "ga_session_number") |&gt;
  mutate(
    session_number = as.integer(param_value),
    user_type = if_else(session_number == 1, "New User", "Returning User")
  ) |&gt;
  group_by(user_pseudo_id, user_type) |&gt;
  summarise(
    sessions = n_distinct(param_value),
    .groups = "drop"
  ) |&gt;
  # Join to purchase data
  left_join(
    ga4_events |&gt;
      filter(event_name == "purchase") |&gt;
      group_by(user_pseudo_id) |&gt;
      summarise(
        purchases = n(),
        revenue = sum(ecommerce_purchase_revenue_in_usd, na.rm = TRUE),
        .groups = "drop"
      ),
    by = "user_pseudo_id"
  ) |&gt;
  mutate(
    purchased = !is.na(purchases),
    purchases = replace_na(purchases, 0L),
    revenue = replace_na(revenue, 0)
  ) |&gt;
  group_by(user_type) |&gt;
  summarise(
    total_users = n(),
    buyers = sum(purchased),
    cvr = buyers / total_users,
    total_revenue = sum(revenue),
    avg_revenue = mean(revenue),
    total_sessions = sum(sessions),
    avg_sessions = mean(sessions),
    .groups = "drop"
  )

user_segments |&gt;
  gt() |&gt;
  tab_header(
    title = "New vs Returning User Behaviour",
    subtitle = "Session and revenue analysis via duckplyr"
  ) |&gt;
  fmt_number(columns = c(total_users, buyers, total_sessions), decimals = 0) |&gt;
  fmt_percent(columns = cvr, decimals = 1) |&gt;
  fmt_currency(columns = c(total_revenue, avg_revenue), currency = "USD") |&gt;
  fmt_number(columns = avg_sessions, decimals = 1) |&gt;
  cols_label(
    user_type = "User Type",
    total_users = "Users",
    buyers = "Buyers",
    cvr = "CVR",
    total_revenue = "Total Revenue",
    avg_revenue = "Avg. Revenue/User",
    total_sessions = "Sessions",
    avg_sessions = "Avg. Sessions"
  ) |&gt;
  opt_stylize(style = 1)
```
